//autogenerated:yes
//nolint:revive,govet,errcheck
package development_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/development"
	"github.com/stretchr/testify/require"
)

func TestEnum_GPS_SYSTEM_ERROR_FLAGS(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.GPS_SYSTEM_ERROR_FLAGS
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.GPS_SYSTEM_ERROR_INCOMING_CORRECTIONS.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.GPS_SYSTEM_ERROR_FLAGS
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.GPS_SYSTEM_ERROR_INCOMING_CORRECTIONS, dec)
	})
}
